#include <stdio.h>

int memo[50];

int fib(int n) {
    if (n <= 1) {
        return n;
    }
    if (memo[n] != 0) {
        return memo[n];
    }
    memo[n] = fib(n - 1) + fib(n - 2);
    return memo[n];
}

int main() {
    printf("%d\n", fib(24));
    return 0;
}
